CREATE POLICY "gestao envia pdf do orcamento" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'orcamentos-pdf' AND (storage.foldername(name))[1] = (public.dono_atual(auth.uid()))::text AND NOT public.has_role(auth.uid(), 'serralheiro'::app_role));
CREATE POLICY "gestao acessa pdf do orcamento" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'orcamentos-pdf' AND (storage.foldername(name))[1] = (public.dono_atual(auth.uid()))::text AND NOT public.has_role(auth.uid(), 'serralheiro'::app_role));
CREATE POLICY "gestao remove pdf do orcamento" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'orcamentos-pdf' AND (storage.foldername(name))[1] = (public.dono_atual(auth.uid()))::text AND NOT public.has_role(auth.uid(), 'serralheiro'::app_role));